using System.Windows.Forms;

static class Program
{
    [STAThread]
    static void Main()
    {
        ApplicationConfiguration.Initialize();

        // .NET 9 breaking change: StatusStrip default renderer changed from
        // ToolStripSystemRenderer to ToolStripProfessionalRenderer.
        // Explicitly set the system renderer to preserve .NET 8 appearance.
        ToolStripManager.RenderMode = ToolStripRenderMode.System;

        Application.Run(new MainForm());
    }
}

using System.Windows.Forms;

class MainForm : Form
{
    private readonly StatusStrip _statusStrip;

    public MainForm()
    {
        _statusStrip = new StatusStrip();
        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }
}

using System;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

class MyPropertyEditor : UITypeEditor
{
    public override object? EditValue(
        System.ComponentModel.ITypeDescriptorContext? context,
        IServiceProvider provider,
        object? value)
    {
        var editorService = provider.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService == null)
            return value;

        var control = CreateDropDownControl(value);

        // .NET 9 breaking change: DropDownControl now throws ArgumentNullException
        // when passed null. Guard against it.
        if (control != null)
        {
            editorService.DropDownControl(control);
            value = ((ListBox)control).SelectedItem;
        }

        return value;
    }

    private Control? CreateDropDownControl(object? currentValue)
    {
        // May return null when no options are available
        var listBox = new ListBox();
        listBox.Items.AddRange(new object[] { "Option1", "Option2", "Option3" });
        if (currentValue != null)
            listBox.SelectedItem = currentValue;
        return listBox;
    }

    public override UITypeEditorEditStyle GetEditStyle(
        System.ComponentModel.ITypeDescriptorContext? context)
    {
        return UITypeEditorEditStyle.DropDown;
    }
}

